public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Check if the starting and ending n-tersection coordinates are valid
    if (start[0] < 0 || start[0] >= n || start[1] < 0 || start[1] >= n || end[0] < 0 || end[0] >= n || end[1] < 0 || end[1] >= n) {
        throw new IllegalArgumentException("Invalid n-tersection coordinates");
    }

    // Check if the paths between adjacent n-tersections are valid
    for (int[] path : paths) {
        if (path[0] < 0 || path[0] >= n || path[1] < 0 || path[1] >= n) {
            throw new IllegalArgumentException("Invalid path between adjacent n-tersections");
        }
    }

    // Initialize a set to keep track of visited n-tersections
    Set<Integer> visited = new HashSet<>();

    // Initialize a queue to keep track of n-tersections to visit
    Queue<Integer> queue = new LinkedList<>();

    // Add the starting n-tersection to the queue
    queue.add(start[0] * n + start[1]);

    // Loop until the queue is empty
    while (!queue.isEmpty()) {
        // Get the next n-tersection to visit
        int current = queue.poll();

        // Check if the current n-tersection is the ending n-tersection
        if (current == end[0] * n + end[1]) {
            return "can be travelled";
        }

        // Check if the current n-tersection has already been visited
        if (visited.contains(current)) {
            continue;
        }

        // Mark the current n-tersection as visited
        visited.add(current);

        // Add the adjacent n-tersections to the queue
        for (int[] path : paths) {
            if (path[0] == current) {
                queue.add(path[1]);
            }
        }
    }

    // If the queue is empty and the ending n-tersection has not been visited, return "cannot be travelled"
    return "cannot be travelled";
}
